/*
 Problem: 3345. Smallest Divisible Digit Product I
 Language: cpp
 Runtime: 0 ms (100.00%)
 Memory: 8.6 MB (74.10%)
 Tags: Math, Enumeration
*/
class Solution {
public:
    int smallestNumber(int n, int t) {
        while (true) {
            int x = n;
            int product = 1;

            while (x) {
                product *= x % 10;
                x /= 10;
            }

            if (product % t == 0) {
                return n;
            }

            n++;
        }
    }
};
